+  auto reduceStackStats = [&] {
+    asm volatile("cp.async.wait_all;" ::: "memory");
+    float query[Q][kVec];
+    loadQueries(query);
+    float stats[kStackStats] = {};
+#pragma unroll
+    for (int n = 0; n < kMaxSources - 1; ++n) {
+      if (n >= p.numStack) break;
+      float src[kVec];
+      unpackBf16(slot16(slots.stack + n), src);
